const findWorkingGroupPeople = `-- name: FindWorkingGroupPeople :many
SELECT p.id, btrim(p.first_name || ' ' || p.last_name)::text AS display_name
FROM people p
WHERE ($1::text = ''
       OR lower(p.first_name || ' ' || p.last_name) LIKE '%' || lower($1::text) || '%')
  AND NOT EXISTS (
      SELECT 1 FROM person_roles pr JOIN roles r ON r.id = pr.role_id
      WHERE pr.person_id = p.id AND r.system_key = 'visitor'
  )
ORDER BY p.last_name, p.first_name, p.id
LIMIT $2
`

type FindWorkingGroupPeopleParams struct {
	Search    string
	PageLimit int32
}

type FindWorkingGroupPeopleRow struct {
	ID          uuid.UUID
	DisplayName string
}

func (q *Queries) FindWorkingGroupPeople(ctx context.Context, arg FindWorkingGroupPeopleParams) ([]FindWorkingGroupPeopleRow, error) {
	rows, err := q.db.Query(ctx, findWorkingGroupPeople, arg.Search, arg.PageLimit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []FindWorkingGroupPeopleRow{}
	for rows.Next() {
		var i FindWorkingGroupPeopleRow
		if err := rows.Scan(&i.ID, &i.DisplayName); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const getWorkingGroup = `-- name: GetWorkingGroup :one
SELECT g.id, g.name, g.description, g.chat_url, g.version,
       lead.person_id AS lead_person_id,
       btrim(lead_person.first_name || ' ' || lead_person.last_name)::text AS lead_display_name,
       (SELECT count(*) FROM working_group_members m WHERE m.group_id = g.id)::bigint AS member_count,
       (SELECT count(*) FROM working_group_machines wm WHERE wm.group_id = g.id)::bigint AS machine_count,
       EXISTS (
           SELECT 1 FROM working_group_members me WHERE me.group_id = g.id AND me.person_id = $1
       ) AS is_member,
       EXISTS (
           SELECT 1 FROM working_group_members me
           WHERE me.group_id = g.id AND me.person_id = $1 AND me.is_lead
       ) AS is_lead,
       (SELECT count(*) FROM working_group_tickets t WHERE t.group_id = g.id AND t.status IN ('new', 'planned'))::bigint AS open_ticket_count,
       (SELECT count(*) FROM working_group_todos d WHERE d.group_id = g.id AND d.done_at IS NULL)::bigint AS open_todo_count
FROM working_groups g
LEFT JOIN working_group_members lead ON lead.group_id = g.id AND lead.is_lead
LEFT JOIN people lead_person ON lead_person.id = lead.person_id
WHERE g.id = $2
`

type GetWorkingGroupParams struct {
	CallerPersonID uuid.UUID
	ID             uuid.UUID
}

type GetWorkingGroupRow struct {
	ID              uuid.UUID
	Name            string
	Description     string
	ChatUrl         *string
	Version         int64
	LeadPersonID    *uuid.UUID
	LeadDisplayName string
	MemberCount     int64
	MachineCount    int64
	IsMember        bool
	IsLead          bool
	OpenTicketCount int64
	OpenTodoCount   int64
}

func (q *Queries) GetWorkingGroup(ctx context.Context, arg GetWorkingGroupParams) (GetWorkingGroupRow, error) {
	row := q.db.QueryRow(ctx, getWorkingGroup, arg.CallerPersonID, arg.ID)
	var i GetWorkingGroupRow
	err := row.Scan(
		&i.ID,
		&i.Name,
		&i.Description,
		&i.ChatUrl,
		&i.Version,
		&i.LeadPersonID,
		&i.LeadDisplayName,
		&i.MemberCount,
		&i.MachineCount,
		&i.IsMember,
		&i.IsLead,
		&i.OpenTicketCount,
		&i.OpenTodoCount,
	)
	return i, err
}

